import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Analytics / Reports — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Analytics / Reports — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/analytics"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Analytics / Reports — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/analytics"}]]},"headers":[],"relativePath":"user-guide/analytics.md","filePath":"user-guide/analytics.md","lastUpdated":1788438242000}'),s={name:"user-guide/analytics.md"};function n(i,e,l,c,p,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="analytics-reports-—-user-guide" tabindex="-1">Analytics / Reports — User Guide <a class="header-anchor" href="#analytics-reports-—-user-guide" aria-label="Permalink to &quot;Analytics / Reports — User Guide&quot;">​</a></h1><p>Catalog slug remains <strong><code>analytics</code></strong>. Marketplace display name is <strong>Reports</strong> (v1.4.0).</p><ol><li>Enable <strong>Reports</strong> from Marketplace (free Operations module; search <code>analytics</code> if needed).</li><li>Open <strong>Overview → Reports</strong> for the executive dashboard (one chart per entitled module). Use the chevron beside <strong>Reports</strong> in the sidebar to expand CRM / Sales / Billing / Purchasing / People without leaving the Reports section.</li><li>Choose a period → <strong>Apply period</strong>.</li><li>Open domain reports from the hub cards or sidebar: <ul><li><strong>CRM report</strong> — Leads + Tasks, plus a <strong>Staff workload</strong> board (open leads/tasks, overdue, cycle times, pressure score 0–100 with healthy / watch / overloaded bands)</li><li><strong>Sales report</strong> — Opportunities, Quotations, Contracts</li><li><strong>Billing report</strong> — Invoices, Payments, Credit Notes</li><li><strong>Purchasing report</strong> — Vendors, Purchase Orders, Expenses</li><li><strong>People report</strong> — Employees, Leave Management, Attendance, Payroll</li></ul></li><li>On each domain page, review KPI cards, per-module charts (pie / donut / bar / area / line by context — e.g. status mix vs value compare), and the breakdown table, then <strong>Export CSV</strong> when sources are available.</li></ol><p>Sections and domain rows appear only when that source module is entitled <strong>and</strong> you have its view permission. On <strong>People</strong>, leave and attendance figures follow the same self-scope as those modules (staff see their own linked employee; managers/approvers see the workspace). Employees totals remain workspace-wide when you have <code>employees.view</code>. <strong>Payroll</strong> appears only with <code>payroll.view</code> (manager+ by default — compensation data is not shown to staff). Dates use <strong>Settings → General → Timezone</strong>.</p><p>For accounting statements (Trial Balance, P&amp;L, Balance Sheet), use <a href="/user-guide/financial-reports">Financial Reports</a>. For department lead/task performance, use <a href="/user-guide/departments">Department reports</a> (owner / department-manager surface — not part of Reports).</p><p><strong>Still deferred:</strong> report builder, saved/scheduled reports, email analytics.</p>',6)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
